std::optional<std::pair<Json,uint64_t>> MappingCanvasGesture::preview(const MappingCanvasDoc& doc)const{if(dragging_&&moved_&&!marquee_&&!original_.is_null())return std::pair{doc.mapping["project"],original_.value("revision",uint64_t(0))};return std::nullopt;}
void MappingCanvasGesture::up(MappingCanvasDoc doc,CanvasPoint at,CanvasRect b,bool shift){
    update(doc,at,b,shift);auto& mapping=doc.mapping;auto& selected=doc.selected;
    if(transform_){if(moved_&&actions.geometry&&!geometryUpdates_.empty())actions.geometry(geometryUpdates_);reset();return;}
    if(!contentDrag_.empty()){auto id=contentDrag_;auto position=contentPosition_;bool changed=moved_;contentDrag_.clear();reset();if(changed&&actions.surfaceProperty)actions.surfaceProperty(id,{{"contentPosition",position}});return;}
    if(!rotationTarget_.is_null()){if(moved_&&!rotationUpdate_.is_null()&&actions.collectionProperty)actions.collectionProperty(rotationTarget_["collection"],rotationUpdate_);rotationTarget_=nullptr;reset();return;}
    if(!bendSurface_.empty()){if(moved_&&!pinUpdate_.is_null()&&actions.surfaceProperty)actions.surfaceProperty(bendSurface_,pinUpdate_);bendSurface_.clear();reset();return;}
    if(!pinSurface_.empty()){if(moved_&&!pinUpdate_.is_null()&&actions.surfaceProperty)actions.surfaceProperty(pinSurface_,pinUpdate_);pinSurface_.clear();reset();return;}
    if(!traceDrag_.empty()){if(moved_&&actions.traceGeometry)for(const auto& trace:mapping["project"]["traces"])if(trace["id"]==traceDrag_){auto id=trace["id"],points=trace["points"];actions.traceGeometry(id,points);break;}traceDrag_.clear();reset();return;}
    if(marquee_&&moved_){selected=additive_?selectionBefore_:Json::array();auto box=[&](const Json& points){double lo[2]={INFINITY,INFINITY},hi[2]={-INFINITY,-INFINITY};for(const auto& p:points){auto s=b.screen(p);lo[0]=std::min(lo[0],s.x);hi[0]=std::max(hi[0],s.x);lo[1]=std::min(lo[1],s.y);hi[1]=std::max(hi[1],s.y);}return lo[0]<marqueeRect_.x+marqueeRect_.w&&hi[0]>marqueeRect_.x&&lo[1]<marqueeRect_.y+marqueeRect_.h&&hi[1]>marqueeRect_.y;};bool surfaces=false;for(const auto& r:mapping["project"]["rects"])if(mappingEditorVisible(mapping,r["id"])&&r.value("kind",std::string{})!="overlay"&&box(r["corners"]))surfaces=true;for(const auto& r:mapping["project"]["rects"])if(mappingEditorVisible(mapping,r["id"])&&(!surfaces||r.value("kind",std::string{})!="overlay")&&box(r["corners"])&&!has(selected,r["id"]))selected.push_back(r["id"]);if(actions.selection)actions.selection(selected);}
    else if(dragging_&&moved_&&corner_<0&&!scale_){if(actions.translation)actions.translation(dragIDs_,offset_);}
    else if(dragging_&&moved_){if(actions.geometry&&!geometryUpdates_.empty())actions.geometry(geometryUpdates_);}
    else if(toggleClick_&&!moved_&&!clickID_.is_null()){selected=selectionBefore_;if(has(selected,clickID_))selected.erase(std::remove(selected.begin(),selected.end(),clickID_),selected.end());else selected.push_back(clickID_);if(actions.selection)actions.selection(selected);}
    else if(dragging_&&!moved_&&!additive_&&!clickID_.is_null()){selected=Json::array({clickID_});if(actions.selection)actions.selection(selected);}
    if(toggleClick_&&moved_&&actions.selection)actions.selection(selected);
    reset();
}
void MappingCanvasGesture::cancel(MappingCanvasDoc doc){if(dragging_&&!original_.is_null())doc.mapping=original_;transform_=false;contentDrag_.clear();traceDrag_.clear();pinSurface_.clear();pinUpdate_=nullptr;bendSurface_.clear();rotationTarget_=nullptr;dragging_=marquee_=false;}
void MappingCanvasGesture::transformDown(MappingCanvasDoc doc,CanvasPoint at,CanvasRect b,bool scale,bool rotate){
    auto& mapping=doc.mapping;start_=at;moved_=false;marquee_=false;corner_=-1;clickID_=nullptr;geometryUpdates_=Json::array();original_=mapping;
    dragIDs_=Json::array();double x=0,y=0;size_t count=0;for(const auto& r:mapping["project"]["rects"])if(has(doc.selected,r["id"])){dragIDs_.push_back(r["id"]);for(const auto& p:mappingEditCorners(r,mapping)){x+=p[0].get<double>();y+=p[1].get<double>();++count;}}
    if(!count){reset();return;}transformCenter_={x/count,y/count};auto c=b.screen(Json::array({transformCenter_.x,transformCenter_.y}));transformVector_={at.x-c.x,at.y-c.y};
    // A press near the centre has no usable radius; use a fixed lever as the Mapper does.
    if(std::hypot(transformVector_.x,transformVector_.y)<48)transformVector_={48,0};
    transform_=dragging_=true;transformScale_=scale;transformRotate_=rotate;
}
bool MappingCanvasGesture::nudgeCorner(MappingCanvasDoc doc,const Json& rectId,size_t index,double dx,double dy){
    for(const auto& r:doc.mapping["project"]["rects"])if(r["id"]==rectId){auto points=mappingEditCorners(r,doc.mapping);if(index>=points.size())return false;auto [owner,point]=mappingPointOwner(doc.mapping,rectId);const double lo=point?-100.:0.,hi=point?100.:1.;
        points[index]=Json::array({std::clamp(points[index][0].get<double>()+dx,lo,hi),std::clamp(points[index][1].get<double>()+dy,lo,hi)});if(actions.geometry)actions.geometry(Json::array({{{"id",rectId},{"corners",points},{"pointReference",point!=nullptr}}}));return true;}
    return false;
}
